 if(scene==='map'){if(['left','right','up','down'].includes(k)){const p=mapPoint(selected),candidates=places.map((_,i)=>({i,p:mapPoint(i)})).filter(a=>k==='left'?a.p.x<p.x:k==='right'?a.p.x>p.x:k==='up'?a.p.y<p.y:a.p.y>p.y);candidates.sort((a,b)=>Math.hypot(a.p.x-p.x,a.p.y-p.y)-Math.hypot(b.p.x-p.x,b.p.y-p.y));if(candidates[0])selected=candidates[0].i;else selected=(selected+(k==='left'||k==='up'?7:1))%8;sound.fx('menu');}if(k==='a')travelTo(selected);if(k==='b'){previous='map';change('settings');}return;}
 if(scene==='races'){const list=raceList();if(k==='up')listScroll=(listScroll+list.length-1)%list.length;if(k==='down')listScroll=(listScroll+1)%list.length;if(k==='left'){filter=(filter+7)%8;listScroll=0;}if(k==='right'){filter=(filter+1)%8;listScroll=0;}if(k==='a'&&list[listScroll])raceIntro(list[listScroll]);if(k==='b')change('map');return;}
 if(scene==='board'){const cols=portrait?3:5;if(k==='left')boardSel=(boardSel+14)%15;if(k==='right')boardSel=(boardSel+1)%15;if(k==='up'){if(boardSel<cols){boardPage=(boardPage+2)%3;boardSel+=15-cols;}else boardSel-=cols;}if(k==='down'){if(boardSel>=15-cols){boardPage=(boardPage+1)%3;boardSel=(boardSel+cols)%15;}else boardSel+=cols;}if(k==='a'){dialog={kind:'patch',patch:data[boardPage*15+boardSel]};change('patch');}if(k==='b')change('map');return;}
