function paintHardware(k,down){document.querySelectorAll('.hardware [data-key="'+k+'"]').forEach(b=>b.classList.toggle('held',down));}
function press(k){paintHardware(k,true);if(keys.has(k))return;keys.add(k);if(scene==='race'||scene==='final'){if(k==='start')doStart();else taps.add(k);}else act(k);}
function release(k){keys.delete(k);paintHardware(k,false);}
function keyMap(e){return {ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',Space:'a',Enter:'a',KeyA:'a',KeyZ:'a',KeyX:'b',KeyB:'b',Escape:'start',KeyP:'start'}[e.code];}
addEventListener('keydown',e=>{if(e.key==='Tab'||e.ctrlKey||e.metaKey||e.altKey)return;
// Let native semantic buttons activate their own action instead of the scene's default A action.
if(e.target.closest?.('#accessible button,.hardware button')&&(e.code==='Enter'||e.code==='Space'))return;
if(scene==='initials'){e.preventDefault();if(e.repeat)return;if(e.key==='Enter'){submitScore();return;}if(/^[a-zA-Z]$/.test(e.key)){initials[initialPos]=e.key.toUpperCase();initialPos=Math.min(2,initialPos+1);scoreNote='';return;}if(e.key==='Backspace'){initialPos=Math.max(0,initialPos-1);return;}const k=keyMap(e);if(k)press(k);return;}if(scene==='lock'){e.preventDefault();if(e.key==='Escape'){codeBuffer='';change('map');}else if(e.key==='Enter')checkCode();else if(e.key==='Backspace')codeBuffer=codeBuffer.slice(0,-1);else if(e.key===' '){lockKey(codeCursor);}else if(e.key.length===1&&/[A-Za-z0-9_-]/.test(e.key)&&codeBuffer.length<64)codeBuffer+=e.key;else if(e.code.startsWith('Arrow'))act(keyMap(e));return;}if(e.code==='KeyM'){e.preventDefault();if(!e.repeat)toggleSound();return;}if(e.code==='KeyF'){e.preventDefault();if(!e.repeat)fullscreen();return;}if(started&&!['race','final','finish','intro','settings','confirm','initials','highscores'].includes(scene)&&/^Digit[1-5]$/.test(e.code)){e.preventDefault();const n=+e.code.slice(-1)-1;n===4?door():openNav(n);return;}const k=keyMap(e);if(k){e.preventDefault();if(!e.repeat)press(k);}});
addEventListener('keyup',e=>{const k=keyMap(e);if(k)release(k);});
// All canvas UI shares one hit map, independent of hidden semantic controls.
// Use the displayed canvas rect, not assumed integer scale (zoom/letterboxing can differ).
function canvasHit(e){const b=canvas.getBoundingClientRect();if(!b.width||!b.height)return null;const x=Math.floor((e.clientX-b.left)*canvas.width/b.width),y=Math.floor((e.clientY-b.top)*canvas.height/b.height);if(x<0||y<0||x>=canvas.width||y>=canvas.height)return null;return [...hits].reverse().find(h=>x>=h.x&&x<h.x+h.w&&y>=h.y&&y<h.y+h.h)||null;}
function activateHit(h){if(!h)return;sound.gesture();if(h.key){press(h.key);setTimeout(()=>release(h.key),70);}else h.fn();render();}
canvas.addEventListener('pointerdown',e=>{if(e.button>0)return;lastPointerClick=null;canvas.focus({preventScroll:true});const h=canvasHit(e);if(!h)return;e.preventDefault();try{canvas.setPointerCapture(e.pointerId);}catch{}if(h.key){pointerKeys.set(e.pointerId,h.key);sound.gesture();press(h.key);render();}else pointerMenus.set(e.pointerId,{id:h.id,scene});});
function pointerEnd(e,cancelled=false){const key=pointerKeys.get(e.pointerId),menu=pointerMenus.get(e.pointerId);pointerKeys.delete(e.pointerId);pointerMenus.delete(e.pointerId);if(key)release(key);if(cancelled)return;const h=canvasHit(e);if(menu&&menu.scene===scene&&h?.id===menu.id)activateHit(h);if(key||menu)lastPointerClick={x:e.clientX,y:e.clientY,until:Date.now()+700};}
canvas.addEventListener('pointerup',e=>pointerEnd(e));
canvas.addEventListener('pointercancel',e=>pointerEnd(e,true));
canvas.addEventListener('lostpointercapture',e=>pointerEnd(e,true));
// Native/synthetic click fallback; suppress the compatibility click after a handled pointer.
canvas.addEventListener('click',e=>{if(e.button>0)return;const p=lastPointerClick;if(p&&Date.now()<p.until&&Math.abs(e.clientX-p.x)<2&&Math.abs(e.clientY-p.y)<2){lastPointerClick=null;return;}e.preventDefault();activateHit(canvasHit(e));});
addEventListener('blur',()=>{keys.clear();taps.clear();pointerKeys.clear();pointerMenus.clear();lastPointerClick=null;if(scene==='race'||scene==='final'){previous=scene;change('settings');}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();if(scene==='race'||scene==='final'){previous=scene;change('settings');}}});
// Real hardware buttons share the exact keyboard/gamepad press/release path.
// Pointer capture supports multi-touch holds; cancel/blur never leaves movement stuck.
const hardwarePointers=new Map(),hardwareClicks=new WeakMap();
for(const button of document.querySelectorAll('.hardware [data-key]')){
 button.addEventListener('pointerdown',e=>{if(e.button>0)return;e.preventDefault();canvas.focus({preventScroll:true});try{button.setPointerCapture(e.pointerId);}catch{}hardwarePointers.set(e.pointerId,{button,key:button.dataset.key});hardwareClicks.set(button,Date.now()+800);sound.gesture();press(button.dataset.key);render();});
 const end=e=>{const held=hardwarePointers.get(e.pointerId);if(!held)return;hardwarePointers.delete(e.pointerId);hardwareClicks.set(button,Date.now()+800);if(![...hardwarePointers.values()].some(p=>p.key===held.key))release(held.key);};
 button.addEventListener('pointerup',end);button.addEventListener('pointercancel',end);button.addEventListener('lostpointercapture',end);
 button.addEventListener('click',e=>{e.preventDefault();if(e.detail>0&&Date.now()<(hardwareClicks.get(button)||0))return;sound.gesture();press(button.dataset.key);render();setTimeout(()=>{if(![...hardwarePointers.values()].some(p=>p.key===button.dataset.key))release(button.dataset.key);},70);});
}
function clearHardware(){hardwarePointers.clear();document.querySelectorAll('.hardware .held').forEach(b=>b.classList.remove('held'));}
addEventListener('blur',clearHardware);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearHardware();});
function gamepad(){const p=navigator.getGamepads?.()[0];if(!p)return;const b=[[0,'a'],[1,'b'],[9,'start'],[12,'up'],[13,'down'],[14,'left'],[15,'right']];for(const [i,k]of b){let d=!!p.buttons[i]?.pressed;if(i===12)d||=p.axes[1]<-.45;if(i===13)d||=p.axes[1]>.45;if(i===14)d||=p.axes[0]<-.45;if(i===15)d||=p.axes[0]>.45;if(d&&!padOld[i])press(k);else if(!d&&padOld[i])release(k);padOld[i]=d;}}
function syncAccessible(){canvas.dataset.scene=scene;canvas.dataset.type=level?.type||'';canvas.dataset.progress=level?.progress?.toFixed(1)||'0';canvas.dataset.collected=save.patches.length;canvas.dataset.score=String(pendingScore);const scoreSummary=scene==='initials'?'Enter three initials. Score '+pendingScore+'. Selected initial '+(initialPos+1)+': '+initials[initialPos]+'. '+scoreNote:scene==='highscores'?'High scores on this device. '+highScores.map((r,i)=>(i+1)+' '+r.initials+' '+r.score+' '+r.mode).join('. '):'';const summary=scoreSummary||(scene==='race'?types[level.type].name+', '+Math.floor(level.progress)+' percent. '+types[level.type].help:scene==='final'?'22B final room. '+level.stars+' stars.':scene==='map'?'World map. '+places[selected].name:scene==='lock'?'22B code entry. '+codeBuffer.length+' characters entered. '+codeMessage:scene+' screen. '+save.patches.length+' patches collected.');if(summary!==lastState){status.textContent=summary;lastState=summary;}const signature=hits.map(a=>a.id+':'+a.label).join('|');if(signature!==lastAccessible){lastAccessible=signature;access.replaceChildren(...hits.map(h=>{const b=document.createElement('button');b.type='button';b.textContent=h.label;b.dataset.action=h.id;b.onclick=()=>{if(h.key){press(h.key);setTimeout(()=>release(h.key),70);}else h.fn();};return b;}));}}
function update(dt){clock+=dt;tick++;gamepad();wipe=Math.max(0,wipe-dt);shake=Math.max(0,shake-dt);if(scene==='race'||scene==='final')levelUpdate(dt);else if(scene==='travel'){travel.t+=dt;if(travel.t>=travel.duration){current=selected=travel.to;if(!save.visited.includes(current))save.visited.push(current);save.place=current;persist();travel=null;change('map');sound.fx('award');}}else if(scene==='finish'){finishAge+=dt;if(finishAge>1.8){dialog={kind:'award',patch:level.patch};finishAge=0;enterInitials();sound.fx('award');}}else if(scene==='award')finishAge+=dt;
 if(!['settings','intro','retry','lock','confirm'].includes(scene))for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=70*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);taps.clear();}
function loop(t){const dt=Math.min(.05,(t-last)/1000||.016);last=t;update(dt);render();requestAnimationFrame(loop);}
async function init(){try{[data,{sha256:lockHash}]=await Promise.all([fetch('data/patches.json').then(r=>r.json()),fetch('data/lock.json').then(r=>r.json())]);save.patches=[...new Set(Array.isArray(save.patches)?save.patches:[])].filter(id=>data.some(p=>p.id===id));save.visited=(Array.isArray(save.visited)?save.visited:[0]).filter(i=>i>=0&&i<8);save.place=Number.isInteger(save.place)&&save.place>=0&&save.place<8?save.place:0;if(!save.visited.includes(0))save.visited.push(0);current=selected=save.place;for(const p of data){const im=new Image();im.src=p.art;imgs[p.id]=im;const thumb=new Image();thumb.src=p.thumbArt;thumbs[p.id]=thumb;}sound.setMute(save.muted,false);scene='title';requestAnimationFrame(loop);}catch(e){scene='error';R(0,0,W,H,0);text('LOAD ERROR. USE HTTP(S).',W/2,H/2,27,1,'center');console.error(e);}}
init();
